 "content": "def transform(grid):
    """Draw an 8 line just beyond the marked shape, opposite the 2 boundary."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # The 2 marker forms a full boundary row or column.
    marker_axis = None
    if all(v == 2 for v in grid[0]) or all(v == 2 for v in grid[-1]):
        marker_axis = "row"
    elif all(row[0] == 2 for row in grid) or all(row[-1] == 2 for row in grid):
        marker_axis = "col"
    if marker_axis is None:
        return out

    colors = {v for row in grid for v in row if v not in (1, 2)}
    if not colors:
        return out
    # The non-background shape is the color other than the background and marker.
    shape_color = max(colors, key=lambda c: sum(v == c for row in grid for v in row))
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == shape_color]
    if marker_axis == "row":
        rmin = min(r for r, _ in points)
        rmax = max(r for r, _ in points)
        marker_at_bottom = all(v == 2 for v in grid[-1])
        line_r = rmin - 1 if marker_at_bottom else rmax + 1
        if 0 <= line_r < h:
            out[line_r] = [8] * w
    else:
        cmin = min(c for _, c in points)
        cmax = max(c for _, c in points)
        marker_at_right = all(row[-1] == 2 for row in grid)
        line_c = cmin - 1 if marker_at_right else cmax + 1
        if 0 <= line_c < w:
            for r in range(h):
                out[r][line_c] = 8
    return out


