{"output": "def transform(grid):
    """Draw a full 8 line beside the non-background shape, toward 2 if space allows."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marker_rows = [r for r in range(h) if all(v == 2 for v in grid[r])]
    marker_cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]

    counts = {}
    for row in grid:
        for v in row:
            if v != 2:
                counts[v] = counts.get(v, 0) + 1
    if not counts:
        return out
    background = max(counts, key=counts.get)
    pts = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (2, background)]
    if not pts:
        return out

    rmin, rmax = min(r for r, _ in pts), max(r for r, _ in pts)
    cmin, cmax = min(c for _, c in pts), max(c for _, c in pts)
    if marker_rows:
        mr = marker_rows[0]
        # The divider is placed just beyond the shape, toward the 2 bar.
        line = rmin - 1 if mr < rmin else rmax + 1
        if 0 <= line < h:
            out[line] = [8] * w
    elif marker_cols:
        mc = marker_cols[0]
        # Reflect the marker's column across the object's bounding box.
        line = cmin + cmax - mc
        if 0 <= line < w:
            for r in range(h):
                out[r][line] = 8
    return out

